package com.essde342.triggerbot.ui.imple; import com.essde342.triggerbot.ui.ISetting; import java.util.*; public class MultiSetting implements ISetting{private final String name;private final Map<String,Boolean> o=new HashMap<>();private final List<String> n=new ArrayList<>();public MultiSetting(String s,String... a){name=s;for(String x:a){n.add(x);o.put(x,false);}}public String getName(){return name;}public boolean isEnabled(String s){return o.getOrDefault(s,false);}public void toggle(String s){if(o.containsKey(s))o.put(s,!o.get(s));}public int getOptionsCount(){return n.size();}public String getOptionName(int i){return i>=0&&i<n.size()?n.get(i):"";}public Object getValue(){return o.toString();}public void fromString(String v){}}